parameters.jsCode:
// Format output AI ke standar Journal Entry umkm-accounting
const aiResponse = JSON.parse($input.first().json.choices[0].message.content);
const webhookData = $('OCR Webhook').first().json.body;

return [{
  json: {
    tenant_id: webhookData.tenant_id,
    date: aiResponse.date,
    description: `Transaksi dari ${aiResponse.vendor}`,
    entries: [
      {
        account_id: aiResponse.category === 'expense' ? 'expense_acct' : 'income_acct',
        debit: aiResponse.category === 'expense' ? aiResponse.total_amount : 0,
        credit: aiResponse.category === 'income' ? aiResponse.total_amount : 0
      },
      {
        account_id: 'cash_acct',
        debit: aiResponse.category === 'income' ? aiResponse.total_amount : 0,
        credit: aiResponse.category === 'expense' ? aiResponse.total_amount : 0
      }
    ]
  }
}];

